function texture(kind,base,accent){const key=kind+base;if(mats[key])return mats[key];const c=document.createElement('canvas');c.width=512;c.height=512;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,512,512);const hex='#'+(accent||'77766b');
