import { createRequire } from 'node:module';
import { join } from 'node:path';
import { mkdirSync, writeFileSync } from 'node:fs';
const runtime=join(process.env.HOME||'/home/runner','.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse((await import('node:fs')).readFileSync(join(runtime,'linux.json'),'utf8'));
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
