import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime=join(process.env.HOME||'/home/runner','.local/share/omgithub-playwright');
const {chromium}=createRequire(join(runtime,'package.json'))('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
page.setDefaultTimeout(15000);
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
try {
 const response=await page.goto('http://127.0.0.1:3000',{waitUntil:'load',timeout:45000});
 console.log('HTTP',response?.status());
 await page.waitForSelector('#main-menu.visible');
 await page.waitForTimeout(1400);
 const click=async selector=>page.locator(selector).evaluate(el=>el.click());
 console.log('MENU',await page.locator('#main-menu h1').innerText());
 await click('[data-action="credits"]');
 await page.waitForSelector('#archive-screen.visible');
 console.log('ARCHIVE DE',await page.locator('#archive-screen h2').innerText(),await page.locator('#archive-screen .panel-intro').innerText());
 await click('#archive-screen [data-action="back"]');
 await click('[data-action="settings"]');
 await click('#settings-screen [data-lang="en"]');
 await click('#settings-screen [data-action="back"]');
 await click('[data-action="credits"]');
 await page.waitForFunction(()=>document.querySelector('#archive-screen h2')?.textContent.includes('ARCHIVE'));
 console.log('ARCHIVE EN',await page.locator('#archive-screen h2').innerText(),await page.locator('#archive-screen .panel-intro').innerText());
 await click('#archive-screen [data-action="back"]');
 await click('[data-action="lobby"]');
 await click('#lobby-screen [data-action="offline"]');
 console.log('OFFLINE DISCLOSURE',await page.locator('#lobby-status').innerText());
 await click('#room-screen [data-action="launch"]');
 await page.waitForSelector('#intro-screen.visible');
 await click('#skip-intro');
 await page.waitForFunction(()=>document.querySelector('#game-ui').classList.contains('active'));
 await page.waitForTimeout(600);
 console.log('GAME INITIAL EQUIPMENT',await page.locator('#equipment').innerText());
 await page.keyboard.press('f');
 console.log('GAME F EQUIPMENT',await page.locator('#equipment').innerText());
 await page.keyboard.press('Escape');
 await page.waitForSelector('#pause-screen.show');
 await click('#pause-screen [data-action="quit"]');
 await page.waitForSelector('#main-menu.visible');
 await page.waitForTimeout(1200);
 mkdirSync('evidence',{recursive:true});
 await page.screenshot({path:'evidence/latest.jpg',type:'jpeg',quality:88});
 console.log('SCREENSHOT evidence/latest.jpg 1280x800 JPEG');
 console.log('BROWSER ERRORS',JSON.stringify(errors));
} finally { await browser.close(); }
