try {
 await page.goto('http://127.0.0.1:3000',{waitUntil:'domcontentloaded',timeout:60000});
 await page.waitForSelector('#main-menu.visible',{timeout:60000});
 await page.waitForTimeout(1000);
 console.log('STATE ACCESS',await page.evaluate(()=>({game:typeof game,bots:typeof bots,mode:game.mode,botCount:game.botCount})));
 await page.locator('[data-action="intro"]').evaluate(el=>el.click());
 await page.waitForTimeout(250);
 await page.locator('#skip-intro').evaluate(el=>el.click());
 await page.waitForFunction(()=>document.querySelector('#game-ui').classList.contains('active'));
 await page.evaluate(()=>{damage(200)});
 await page.waitForSelector('#down-overlay.show');
 console.log('DOWN',await page.evaluate(()=>({down:game.playerDown,bots:bots.length,health:game.health,revive:game.revive})));
 await page.waitForTimeout(2000);
 const botOnly=await page.evaluate(()=>({revive:game.revive,meter:document.querySelector('#down-overlay .revive-meter i').style.width}));
 console.log('BOT ASSIST AFTER 2S',botOnly);
 await page.keyboard.down('e');
 await page.waitForTimeout(2000);
 const held=await page.evaluate(()=>({down:game.playerDown,health:game.health,revive:game.revive,meter:document.querySelector('#down-overlay .revive-meter i').style.width}));
 console.log('HELD E AFTER 2S MORE',held);
 await page.keyboard.up('e');
 if(held.down){await page.waitForTimeout(1500)}
 console.log('REVIVED',await page.evaluate(()=>({down:game.playerDown,health:game.health,overlay:document.querySelector('#down-overlay').classList.contains('show')})));
 console.log('BROWSER ERRORS',JSON.stringify(errors));
} finally {await browser.close()}
