const runtime=join(process.env.HOME||'/home/runner','.local/share/omgithub-playwright');const{chromium}=createRequire(join(runtime,'package.json'))('playwright');const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));const browser=await chromium.launch({...config.browser.launchOptions});const context=await browser.newContext({viewport:{width:1280,height:800}});const page=await context.newPage();page.setDefaultTimeout(30000);const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.route('**/src/game.js',async route=>{const response=await route.fetch();await route.fulfill({response,body:(await response.text())+'\nwindow.__reviveTest={game,bots,damage};'});});try{const response=await page.goto('http://127.0.0.1:3000',{waitUntil:'domcontentloaded',timeout:60000});console.log('HTTP',response?.status());await page.waitForFunction(()=>document.querySelector('#main-menu.visible [data-action="intro"]'));await page.locator('[data-action="intro"]').click();await page.waitForSelector('#intro-screen.visible',{timeout:15000}).catch(()=>{});await page.locator('#skip-intro').click({timeout:15000});await page.waitForFunction(()=>document.querySelector('#game-ui').classList.contains('active'));console.log('START',await page.evaluate(()=>({mode:window.__reviveTest.game.mode,bots:window.__reviveTest.bots.length})));await page.evaluate(()=>window.__reviveTest.damage(200));await page.waitForSelector('#down-overlay.show');await page.waitForTimeout(10000);const botOnly=await page.evaluate(()=>({down:window.__reviveTest.game.playerDown,health:window.__reviveTest.game.health,revive:window.__reviveTest.game.revive,overlay:document.querySelector('#down-overlay').classList.contains('show'),bots:window.__reviveTest.bots.length}));console.log('BOT-ASSIST COMPLETION',botOnly);await page.evaluate(()=>{window.__reviveTest.bots.length=0;window.__reviveTest.game.damageCooldown=0;window.__reviveTest.damage(100)});await page.waitForFunction(()=>window.__reviveTest.game.playerDown);await page.keyboard.down('e');await page.waitForTimeout(5500);await page.keyboard.up('e');const held=await page.evaluate(()=>({down:window.__reviveTest.game.playerDown,health:window.__reviveTest.game.health,revive:window.__reviveTest.game.revive,overlay:document.querySelector('#down-overlay').classList.contains('show'),bots:window.__reviveTest.bots.length}));console.log('HELD-E COMPLETION WITHOUT BOTS',held);console.log('BROWSER ERRORS',JSON.stringify(errors));}finally{await browser.close()}
